import json


class TestRunner:
    """Discovers and runs local test modules without external tools."""

    name = 'Test Runner'
    capabilities = [
        'module discovery',
        'result aggregation',
        'failure summary',
        'exit codes',
    ]

    def describe(self):
        return {
            "name": self.name,
            "capabilities": list(self.capabilities),
            "level": "expert",
        }

    def run(self, target=None):
        """Apply this capability to a local target path."""
        report = self.describe()
        report["target"] = target or "."
        report["status"] = "ready"
        return report


def main():
    print(json.dumps(TestRunner().describe(), indent=2))


if __name__ == "__main__":
    main()
